const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const houston = ee.Geometry.Point([-95.3698, 29.7604]); // Approximate center of Houston, TX

  const dateMay18Start = '2024-05-18';
  const dateMay18End = '2024-05-19'; // End date is exclusive

  const dateAprilStart = '2024-04-01';
  const dateAprilEnd = '2024-05-01'; // End date is exclusive

  // 2. Data Acquisition
  const viirsCollection = ee.ImageCollection('NOAA/VIIRS/DNB/V2/VCMSL');

  // Function to mask out poor quality pixels (clouds, stray light)
  // QF_DNB band: Bit 0 = Stray Light, Bit 1 = Cloud Mask, Bit 2 = High-EO
  // We want QF_DNB to be 0 for good quality (no stray light, no clouds, no high-EO).
  const maskBadQuality = function(image) {
    const qfDnb = image.select('QF_DNB');
    // Keep pixels where QF_DNB is 0 (good quality, no clouds, no stray light, no high-EO)
    // The VIIRS DNB product uses a 15-bit mask. The first three bits are important.
    // Bit 0: Stray Light (0 = no, 1 = yes)
    // Bit 1: Cloud Mask (0 = clear, 1 = cloudy)
    // Bit 2: High-EO (0 = no, 1 = yes)
    // So, we want (QF_DNB & 7) == 0 for best quality.
    const goodQualityMask = qfDnb.bitwiseAnd(7).eq(0);
    return image.updateMask(goodQualityMask);
  };

  // Filter for May 18, 2024
  let may18Col = viirsCollection
    .filterBounds(houston)
    .filterDate(dateMay18Start, dateMay18End)
    .map(maskBadQuality)
    .select('avg_rad'); // Select average radiance band

  // Filter for April 2024
  let aprilCol = viirsCollection
    .filterBounds(houston)
    .filterDate(dateAprilStart, dateAprilEnd)
    .map(maskBadQuality)
    .select('avg_rad');

  // Check collection sizes (C1)
  const may18Size = await may18Col.size().getInfo();
  const aprilSize = await aprilCol.size().getInfo();

  console.log(`May 18, 2024 images (after quality mask): ${may18Size}`);
  console.log(`April 2024 images (after quality mask): ${aprilSize}`);

  if (may18Size === 0 || aprilSize === 0) {
    console.log("C1: Empty Collection (No valid images found for one or both periods after quality masking).");
    return;
  }

  // Aggregate images for comparison
  const may18Image = may18Col.mean(); // Mean of images for May 18 (usually just one)
  const aprilImage = aprilCol.mean(); // Mean of images for April

  // Calculate pixel count to detect C2 (no valid pixels after masking)
  const scale = 1000; // Use a coarser scale to avoid memory issues and speed up
  const maxPixels = 1e9;

  const may18PixelCount = await may18Image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: houston,
    scale: scale,
    maxPixels: maxPixels
  }).get('avg_rad').getInfo();

  const aprilPixelCount = await aprilImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: houston,
    scale: scale,
    maxPixels: maxPixels
  }).get('avg_rad').getInfo();

  console.log(`May 18, 2024 valid pixels: ${may18PixelCount}`);
  console.log(`April 2024 valid pixels: ${aprilPixelCount}`);

  if (may18PixelCount === 0 || aprilPixelCount === 0) {
    console.log("C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain in the region of interest).");
    return;
  }

  // 4. Calculation
  const may18Brightness = await may18Image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: houston,
    scale: scale,
    maxPixels: maxPixels
  }).get('avg_rad').getInfo();

  const aprilBrightness = await aprilImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: houston,
    scale: scale,
    maxPixels: maxPixels
  }).get('avg_rad').getInfo();

  // 5. Validation & Final Answer
  if (may18Brightness === null || isNaN(may18Brightness) ||
      aprilBrightness === null || isNaN(aprilBrightness)) {
    console.log("C3: Calculation Failure (Result is None, NaN, or invalid).");
    return;
  }

  console.log(`Mean Nighttime Brightness (May 18, 2024): ${may18Brightness.toFixed(4)} nW/cm²/sr`);
  console.log(`Mean Nighttime Brightness (April 2024): ${aprilBrightness.toFixed(4)} nW/cm²/sr`);

  if (may18Brightness < aprilBrightness) {
    console.log("A"); // Yes, it decreased
  } else {
    console.log("B"); // No, it did not decrease
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
